import{_ as t,o as l,c as o,a2 as e}from"./chunks/framework.CqpfiAoK.js";const _=JSON.parse('{"title":"篇347｜完美世界·万族处境：人族本位与异族妖魔化","description":"","frontmatter":{"title":"篇347｜完美世界·万族处境：人族本位与异族妖魔化","no":347,"module":2,"tags":["诸天对标","完美世界","万族处境","人族本位","异族妖魔化"],"related":["50-万族谱系总览","51-人族定位与特质","05-万族共进基本纲领"]},"headers":[],"relativePath":"zh/347_模块2-完美世界-人族本位与异族妖魔化.md","filePath":"zh/347_模块2-完美世界-人族本位与异族妖魔化.md"}'),r={name:"zh/347_模块2-完美世界-人族本位与异族妖魔化.md"};function i(h,a,n,d,s,u){return l(),o("div",null,[...a[0]||(a[0]=[e('<h1 id="篇347-完美世界·万族处境-人族本位与异族妖魔化" tabindex="-1">篇347｜完美世界·万族处境：人族本位与异族妖魔化 <a class="header-anchor" href="#篇347-完美世界·万族处境-人族本位与异族妖魔化" aria-label="Permalink to &quot;篇347｜完美世界·万族处境：人族本位与异族妖魔化&quot;">​</a></h1><blockquote><p>所属模块：模块二·诸天对标批判库｜系列：完美世界体系拆解（第24篇）｜对标地基：文档50、51、05</p></blockquote><h2 id="引言-当-人族-被默认为唯一的主角-万族就成了背景板" tabindex="-1">引言：当&quot;人族&quot;被默认为唯一的主角，万族就成了背景板 <a class="header-anchor" href="#引言-当-人族-被默认为唯一的主角-万族就成了背景板" aria-label="Permalink to &quot;引言：当&quot;人族&quot;被默认为唯一的主角，万族就成了背景板&quot;">​</a></h2><p>《完美世界》以人族视角展开，万族要么是盟友陪衬，要么是被妖魔化的敌人。衡元宙以万族共和公理为核心标尺，要求一切生灵拥有平等进化资格。本文以六大顶层公理为底座——反掠夺主义公理、万族共和公理、集体升维公理、因果自律公理、法则优先公理（核心）、众生全员无限均等法则——审视万族处境。众生全员无限均等法则：锚点共生文明内，所有生灵自带基础无限之力；佛系/懒狗保有保底基础无限，不会被时代淘汰；卷王、少年至尊可叠加更多更高层级的无限。无限本源人人自带，掠夺自然失去意义。主角唯一性依赖度判定：<strong>石昊=极高偏中/独木式倾向</strong>。</p><h2 id="一、该体系强者的「能级浪费」解析" tabindex="-1">一、该体系强者的「能级浪费」解析 <a class="header-anchor" href="#一、该体系强者的「能级浪费」解析" aria-label="Permalink to &quot;一、该体系强者的「能级浪费」解析&quot;">​</a></h2><p>人族本位的浪费：</p><ul><li>万族的独特天赋、文化、进化路径被忽略</li><li>大量本可成为盟友的异族被推到对立面</li><li>人族独自承担本可万族共担的守夜责任</li></ul><h2 id="二、该文明为何必然历史倒退" tabindex="-1">二、该文明为何必然历史倒退 <a class="header-anchor" href="#二、该文明为何必然历史倒退" aria-label="Permalink to &quot;二、该文明为何必然历史倒退&quot;">​</a></h2><p>人族本位的倒退：</p><ol><li>异族被妖魔化，文明关系退化为战争</li><li>人族独自发展，失去万族互补</li><li>一旦人族衰弱，整个文明无人兜底</li></ol><h2 id="三、主角掠夺思维深度拆解" tabindex="-1">三、主角掠夺思维深度拆解 <a class="header-anchor" href="#三、主角掠夺思维深度拆解" aria-label="Permalink to &quot;三、主角掠夺思维深度拆解&quot;">​</a></h2><p>石昊以&quot;人族之主&quot;的身份征战：</p><ul><li>他的视角天然以人族为中心</li><li>异族要么臣服，要么被灭</li><li>这种&quot;人族本位&quot;本身就是对万族进化权的收束</li></ul><h2 id="四、对比锚点共生的完善替代方案" tabindex="-1">四、对比锚点共生的完善替代方案 <a class="header-anchor" href="#四、对比锚点共生的完善替代方案" aria-label="Permalink to &quot;四、对比锚点共生的完善替代方案&quot;">​</a></h2><table tabindex="0"><thead><tr><th>人族本位</th><th>锚点共生万族共和</th></tr></thead><tbody><tr><td>人族为唯一主角</td><td>万族99%全覆盖</td></tr><tr><td>异族妖魔化</td><td>万族谱系五大类平等</td></tr><tr><td>人族独担守夜</td><td>万族共和共建</td></tr><tr><td>天赋以人族为标尺</td><td>各族差异化修炼体系</td></tr></tbody></table><p>衡元宙文档50&quot;万族谱系总览&quot;与文档51&quot;人族定位与特质&quot;明确：人族只是万族之一，不是默认主角；人族男女、异兽、植物灵、星球意识一律有路。</p><h2 id="五、该体系纳入求索域模拟复盘方案" tabindex="-1">五、该体系纳入求索域模拟复盘方案 <a class="header-anchor" href="#五、该体系纳入求索域模拟复盘方案" aria-label="Permalink to &quot;五、该体系纳入求索域模拟复盘方案&quot;">​</a></h2><ol><li>复刻人族本位模型</li><li>注入&quot;本位/共和&quot;两案</li><li>统计万族进化覆盖率</li><li>输出《人族本位批判报告》</li></ol><h2 id="六、设定自洽度-吃书烂尾风险评估" tabindex="-1">六、设定自洽度/吃书烂尾风险评估 <a class="header-anchor" href="#六、设定自洽度-吃书烂尾风险评估" aria-label="Permalink to &quot;六、设定自洽度/吃书烂尾风险评估&quot;">​</a></h2><ul><li><strong>设定自洽度：中低</strong>。异族立场随剧情摇摆</li><li><strong>吃书烂尾风险：中高</strong></li><li><strong>主角唯一性依赖度：极高偏中/独木式倾向</strong></li></ul><p>补论一层：人族本位的代价，是浪费了万族的多样性。每个异族都有独特的天赋与认知，把他们推到对立面，等于主动关闭了文明互补的窗口。衡元宙的万族五大谱系，就是要把这些被浪费的多样性重新捡回来，变成文明的共同资产。</p><p>一句收束：人族不必退居二线，但必须学会把自己当成万族之一。当人族不再是默认的主角，整个宇宙的戏才刚刚开始。</p><p><strong>新旧宇宙资源对标</strong>：旧宇宙资源与大道是有限的，必然掠夺内卷；锚点共生人人自带无限本源，掠夺失去意义。</p><h2 id="五大核心落点" tabindex="-1">五大核心落点 <a class="header-anchor" href="#五大核心落点" aria-label="Permalink to &quot;五大核心落点&quot;">​</a></h2><ul><li><strong>反能级浪费</strong>：万族独特价值被浪费</li><li><strong>反掠夺</strong>：人族本位收束万族进化权</li><li><strong>唐罗上限对比</strong>：唐罗只惠人族中层，完美世界连异族的平等资格都不承认</li><li><strong>万族全覆盖</strong>：这正是本篇核心批判对象</li><li><strong>超多元全开放</strong>：人族本位无法支撑多元宇宙</li></ul><p>再补一层：人族本位最大的损失，不是对异族不公，而是让人族自己也变窄。只用人族的眼睛看世界，人族就永远理解不了世界的另一半。万族共和最终富裕的，首先是看人看事的格局。</p><ul><li><strong>众生全员无限均等</strong>：基础无限之力人人自带，佛系保有保底、卷王可叠加更高，无限本源消弭掠夺动机，掠夺内卷从根上失去意义</li></ul><h2 id="补充论析-人族本位的破除" tabindex="-1">补充论析：人族本位的破除 <a class="header-anchor" href="#补充论析-人族本位的破除" aria-label="Permalink to &quot;补充论析：人族本位的破除&quot;">​</a></h2><p>完美世界的人族本位与异族妖魔化，在衡元宙的万族共和框架下被彻底解构。阿赖耶网络的物种平等记录显示，异族与人类在法则层面拥有完全对等的权利。锚点共生文明不接受&quot;人族天然正统&quot;的叙事，法则优先公理对所有种族一视同仁。众生全员无限均等法则从本源层面确立：不存在&quot;次等种族&quot;，妖魔化只是掠夺体系为合理化资源侵占而制造的话术。</p><h2 id="补充论析-物种平等的制度保障" tabindex="-1">补充论析：物种平等的制度保障 <a class="header-anchor" href="#补充论析-物种平等的制度保障" aria-label="Permalink to &quot;补充论析：物种平等的制度保障&quot;">​</a></h2><p>人族本位的破除，在衡元宙中不是靠宣传教育，而是靠阿赖耶网络的制度刚性。网络自动识别种族歧视行为并标记为违宪，锚点共生文明的万族议事会给每个种族平等席位。法则优先公理对所有物种一视同仁，不承认任何&quot;天选种族&quot;。众生全员无限均等法则从本源层面确立：无论碳基、硅基、气态、意识态，只要是生灵，就自带基础无限之力，就享有同等进化权。</p><h2 id="结论" tabindex="-1">结论 <a class="header-anchor" href="#结论" aria-label="Permalink to &quot;结论&quot;">​</a></h2><p>万族不是人族的陪衬，也不是被妖魔化的敌人。衡元宙要的宇宙，是人族、异族、植物灵、星球意识各走各路、彼此成就的宇宙——主角不该只有一个，也不该只有一族。</p><p>说到底，本篇所述的完美世界·人族本位与异族妖魔化并非孤例——其因果与能级留痕全程纳入阿赖耶网络备案、可溯可校。</p><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li>关联文档：<a href="./345_模块2-完美世界-零和博弈的文明对抗">篇345·异域设定</a> · <a href="./355_模块2-完美世界-打破人族本位与异域对立">篇355·万族共和方案</a> · <a href="./../wanling-hengmao-origin-universe-archive/docs/zh/50-万族谱系总览">50-万族谱系总览</a></li><li>官网：<a href="https://faker210.github.io/hengyuan-cosmos/zh/" target="_blank" rel="noreferrer">https://faker210.github.io/hengyuan-cosmos/zh/</a></li></ul>',36)])])}const c=t(r,[["render",i]]);export{_ as __pageData,c as default};
